// Question: does a dated document list and spacious, unassisted editor provide a useful minimal base?
const seed=()=>({name:'Jordan Davis',focuses:[{id:1,title:'Position focus · 2026',start:'2026-01-01',end:'2026-12-31',sections:[]},{id:2,title:'Position focus · 2025',start:'2025-01-01',end:'2025-12-31',sections:[{kind:'Core objective',objective:'Build and release a clearer next-step screen for one video devotional, using AI to help write code.',goals:['Test with 20 viewers by the end of Month 1 and record how many find the next step.','By Month 6, retest with 20 viewers; at least 16 can find the next step.']}]}]});
let s=seed(),page='list',selected=1,topic='Objectives',saved='';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const focus=()=>s.focuses.find(f=>f.id===selected);
const button=(label,action,cls='')=>`<button class="${cls}" data-action="${action}">${label}</button>`;
const date=x=>x?new Date(x+'T12:00:00').toLocaleDateString('en-NZ',{day:'numeric',month:'short',year:'numeric'}):'No date';
function state(){document.querySelector('#state').textContent=JSON.stringify(s,null,2)}
function go(p){page=p;saved='';render();window.scrollTo(0,0)}
function render(){document.querySelector('#app').innerHTML=`<aside><div class="brand"><span>♙</span> Lantern</div><nav>${[['list','◎','Position focuses'],['guide','▤','Guide'],['account','⚙','Account']].map(([p,i,t])=>button(i+'　'+t,'nav:'+p,(page===p||p==='list'&&page==='editor')?'active':'')).join('')}</nav><div class="aside-foot">Navy / focused base<br>Fourth prototype · menu under review</div></aside><main class="main"><div class="demo"><span>PROTOTYPE · Temporary memory · Refresh clears changes</span>${button('Reset demo','reset')}</div><div class="workspace">${page==='list'?list():page==='editor'?editor():page==='guide'?guide():account()}<details class="state"><summary>Prototype state</summary><pre id="state"></pre></details></div></main>`;state()}
function list(){return `<header><div><h1>Position focuses</h1><p class="muted">Your documents, organised by period.</p></div>${button('New position focus','new','primary')}</header><table class="focus-list"><thead><tr><th>Document</th><th>Period</th><th></th></tr></thead><tbody>${[...s.focuses].sort((a,b)=>b.start.localeCompare(a.start)).map(f=>`<tr><td>${button(esc(f.title),'open:'+f.id,'link')}</td><td class="period">${date(f.start)} – ${date(f.end)}</td><td>${button('Open','open:'+f.id)}</td></tr>`).join('')}</tbody></table><p class="muted" style="margin-top:24px">The current document starts empty. The 2025 document contains an illustrative example.</p>`}
function editor(){const f=focus();return `${button('← Position focuses','nav:list','link back')}<header><div><h1>${esc(f.title)}</h1><p class="muted">${date(f.start)} – ${date(f.end)}</p></div>${button('Save document','save','primary')}</header><label for="title">Document title</label><input id="title" data-field="title" value="${esc(f.title)}"><div class="metadata"><div><label for="start">Period starts</label><input id="start" type="date" data-field="start" value="${f.start}"></div><div><label for="end">Period ends</label><input id="end" type="date" data-field="end" value="${f.end}"></div></div>${f.sections.length?f.sections.map((x,i)=>`<section class="focus-section"><div class="row"><h2>Objective ${i+1}${x.kind!=='Core objective'?`<span class="badge">${esc(x.kind)}</span>`:''}</h2>${button('Remove objective','remove:'+i,'link danger')}</div><label for="objective-${i}">Objective</label><textarea class="objective" id="objective-${i}" data-section="${i}" data-objective placeholder="Write your objective…">${esc(x.objective)}</textarea><h3 style="margin-top:32px">SMART goals</h3>${x.goals.map((g,j)=>`<div class="goal-edit"><div class="row"><label for="goal-${i}-${j}">Goal ${j+1}</label>${button('Remove goal',`removegoal:${i}:${j}`,'link danger')}</div><textarea class="goaltext" id="goal-${i}-${j}" data-section="${i}" data-goal="${j}" placeholder="Write your goal…">${esc(g)}</textarea></div>`).join('')}${button('+ Add SMART goal','goal:'+i)}</section>`).join(''):`<div class="empty-base"><h2>A blank position focus</h2><p class="muted">Add your first objective when you’re ready.</p>${button('Add objective','add:Core objective','primary')}</div>`}<div class="editor-actions"><div>${button('+ Add objective','add:Core objective')} ${button('+ Add optional focus','optional')}</div><span class="save-status" id="save-status">${esc(saved)}</span></div>`}
function guide(){return `<header><div><h1>Guide</h1><p class="muted">A short reference to read separately from your document.</p></div></header><div class="tabs">${['Objectives','SMART goals','Example'].map(t=>button(t,'topic:'+t,topic===t?'active':'')).join('')}</div><div class="card guide-copy">${topic==='Objectives'?`<h2>Describe the outcome you want to achieve</h2><p>An objective gives your work a clear purpose. Say who it serves and what you want to change.</p><div class="visual"><div><b>People</b>Who you serve</div><span>→</span><div><b>Outcome</b>What changes</div><span>→</span><div><b>Contribution</b>Why it matters</div></div>`:topic==='SMART goals'?`<h2>Make the objective actionable</h2><p>Write a specific action, a measurable result, and a time frame. Check that it is achievable and relevant to the objective.</p><div class="visual"><div><b>Action</b>What you will do</div><span>+</span><div><b>Measure</b>What success means</div><span>+</span><div><b>Time</b>By when</div></div>`:`<h2>Example objective</h2><p>Build and release a clearer next-step screen for one video devotional, using AI to help write code.</p><h2>SMART goal</h2><p>By Month 6, test with 20 viewers; at least 16 can find the next step.</p><small>Illustrative target and timing.</small>`}</div>`}
function account(){return `<header><h1>Account</h1></header><div class="card"><label for="name">Display name</label><input id="name" value="${esc(s.name)}" data-name><p class="muted" style="margin:24px 0">jordan@example.test · Demo account</p>${button('Save name','savename','primary')}</div>`}
function modal(html){document.querySelector('#modal').innerHTML=html;document.querySelector('#modal').showModal()}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(window.timer);window.timer=setTimeout(()=>el.style.display='none',2500)}
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.field)focus()[el.dataset.field]=el.value;if(el.hasAttribute('data-objective'))focus().sections[+el.dataset.section].objective=el.value;if(el.hasAttribute('data-goal'))focus().sections[+el.dataset.section].goals[+el.dataset.goal]=el.value;if(el.hasAttribute('data-name'))s.name=el.value;saved='Unsaved changes';const status=document.querySelector('#save-status');if(status)status.textContent=saved;state()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const [a,v,j]=b.dataset.action.split(':');if(a==='nav')go(v);if(a==='open'){selected=+v;go('editor')}if(a==='new'){const id=Date.now();s.focuses.unshift({id,title:'Untitled position focus',start:'',end:'',sections:[]});selected=id;go('editor')}if(a==='add'){focus().sections.push({kind:v,objective:'',goals:['']});document.querySelector('#modal').close();render();document.querySelectorAll('textarea.objective').item(focus().sections.length-1).focus()}if(a==='goal'){focus().sections[+v].goals.push('');render();document.querySelectorAll(`[data-section="${v}"][data-goal]`).item(focus().sections[+v].goals.length-1).focus()}if(a==='remove'||a==='removegoal')modal(`<h2>Remove this ${a==='remove'?'objective and its goals':'goal'}?</h2><p>This changes only your temporary document.</p>${button('Remove',`confirm${a}:${v}${j===undefined?'':':'+j}`,'danger')} ${button('Cancel','close')}`);if(a==='confirmremove'){focus().sections.splice(+v,1);document.querySelector('#modal').close();render()}if(a==='confirmremovegoal'){focus().sections[+v].goals.splice(+j,1);document.querySelector('#modal').close();render()}if(a==='optional')modal(`<h2>Add an optional focus</h2><p>The same objective and SMART goals, with a label for its purpose.</p><div class="stack">${button('Personal development','add:Personal development')}${button('Leadership initiative','add:Leadership initiative')}</div><p style="margin-top:24px">${button('Cancel','close')}</p>`);if(a==='close')document.querySelector('#modal').close();if(a==='save'){saved='Saved in this session';render();toast(saved)}if(a==='savename')toast('Name saved in this session');if(a==='topic'){topic=v;render()}if(a==='reset'){s=seed();selected=1;go('list');toast('Demo reset')}});
render();
